let current=0,elapsed=0,last=performance.now(),paused=false,duration=20000;
const $=id=>document.getElementById(id);let bounds=[6,94];
try{const s=JSON.parse(localStorage.getItem('legolu')||'null');if(s){bounds=s.bounds;duration=s.timingVersion===2?s.duration:20000;$('arrows').checked=s.arrows}}catch{}
$('left').value=bounds[0];$('right').value=bounds[1];$('seconds').value=duration/1000;
slides.forEach((s,i)=>{const b=document.createElement('button');b.title=`Slide ${i+1}: ${s.title.replace(/<[^>]*>/g,' ')}`;b.setAttribute('aria-label',b.title);b.onclick=()=>go(i);$('rail').append(b)});
function assemblyArtwork(){return `<div class="picture"><div class="circle-art assembly" role="img" aria-label="Colourful building bricks assemble into a Durga doll"><div class="assembled-still"><img src="assets/goddess-9.jpeg" alt=""></div>${Array.from({length:64},(_,i)=>{const col=i%8,row=Math.floor(i/8),angle=i*2.39996;return `<div class="brick-piece" style="--col:${col};--row:${row};--x:${Math.cos(angle)*240}px;--y:${Math.sin(angle)*240}px;--spin:${(i%7-3)*25}deg;--delay:${1.5+row*.4+(col%3)*.22}s;--tile:${['#ce3038','#f1c536','#2674bf','#2b8452'][i%4]}"><img src="assets/goddess-9.jpeg" alt="" style="left:${-col*100}%;top:${-row*100}%"></div>`}).join('')}</div></div>`}
function render(){const s=slides[current];$('brand').innerHTML=brickLogo;$('count').textContent=`${String(current+1).padStart(2,'0')} / ${slides.length}`;$('stage').innerHTML=`<section class="slide ${s.gallery?'wide':''}"><div class="copy"><div class="eyebrow">${s.tag}</div><h1 class="${s.hero?'hero':''}">${s.title}</h1><p class="story">${s.text}</p>${s.lesson?`<div class="lesson">${s.lesson}</div>`:''}</div>${s.gallery?`<div class="gallery">${goddesses.map(g=>`<div><img src="assets/goddess-${g[1]}.jpeg" alt="${g[0]} LEGO illustration"><span>${g[0]}</span></div>`).join('')}</div>`:s.assembly?assemblyArtwork():s.art?`<div class="picture"><div class="circle-art"><img src="assets/${s.art}" alt="${s.artAlt}"></div></div>`:s.image!==undefined?`<div class="picture"><img src="assets/goddess-${s.image}.jpeg" alt="${s.goddess!==undefined?goddesses[s.goddess][0]:'Goddess Durga'} LEGO illustration"></div>`:`<div class="picture"><div class="motif" aria-hidden="true">${s.motif}</div></div>`}</section>`;[...$('rail').children].forEach((b,i)=>{b.className=i===current?'active':i<current?'seen':'';b.setAttribute('aria-current',i===current?'step':'false')});positionPointer()}
function positionPointer(){const s=slides[current],g=s.goddess;$('pointer').hidden=!$('arrows').checked||(g===undefined&&!s.down);$('pointer').style.left=(g===undefined?50:bounds[0]+g*(bounds[1]-bounds[0])/8)+'%';$('pointerLabel').textContent=g===undefined?'OUR GOLU PADI':`${g+1} · ${goddesses[g][0]}`}
function updateCountdown(){const remaining=Math.max(0,duration-elapsed);$('countdown').textContent=paused||$('setup').open?'Paused':`${Math.ceil(remaining/1000)}s · next slide ↓`;$('timeFill').style.transform=`scaleX(${remaining/duration})`;}
function go(i){current=(i+slides.length)%slides.length;elapsed=0;render();updateCountdown()}
function tick(t){if(!paused&&!$('setup').open){elapsed+=Math.min(t-last,1000);if(elapsed>=duration)go(current+1)}last=t;updateCountdown();requestAnimationFrame(tick)}
$('previous').onclick=()=>go(current-1);$('next').onclick=()=>go(current+1);function pause(){paused=!paused;document.body.classList[paused?'add':'remove']('slideshow-paused');$('pause').textContent=paused?'Play':'Pause'}$('pause').onclick=pause;
async function fullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}}$('fullscreen').onclick=fullscreen;
$('settings').onclick=()=>$('setup').showModal();$('close').onclick=()=>$('setup').close();for(const id of ['left','right','seconds','arrows'])$(id).oninput=()=>{bounds=[+$('left').value,+$('right').value];duration=Math.max(5,Math.min(60,+$('seconds').value||20))*1000;elapsed=0;positionPointer();try{localStorage.setItem('legolu',JSON.stringify({bounds,duration,timingVersion:2,arrows:$('arrows').checked}))}catch{}};
let hide;document.addEventListener('pointermove',()=>{document.body.classList.add('controls');clearTimeout(hide);hide=setTimeout(()=>document.body.classList.remove('controls'),2500)});
document.addEventListener('keydown',e=>{if($('setup').open||/INPUT|BUTTON/.test(document.activeElement.tagName))return;if(['ArrowRight','ArrowLeft',' '].includes(e.key))e.preventDefault();if(e.key==='ArrowRight')go(current+1);if(e.key==='ArrowLeft')go(current-1);if(e.key===' ')pause();if(e.key.toLowerCase()==='f')fullscreen();if(e.key.toLowerCase()==='m')toggleMusic()});
